define({"topics":[{"title":"Applying LOTO - MDP","shortdesc":"<p class=\"shortdesc\"><span class=\"ph uicontrol\">Note: <\/span>Prior to applying LOTO to the system do the Disk Wipe procedure, which can be found on the documentation library. Search on document 5500610-1. Apply LOTO to the MDP or the facility PDU before removing power to these items. Facility-level LOTO must be done by an electrician.<\/p>","href":"t_Applying-LOTO-MDP-Premier_4.html","attributes":{"data-id":"id_2001934"},"menu":{"hasChildren":false},"tocID":"id_2001934-d46e98410","topics":[]},{"title":"Tightening connections<span class=\"ph\"> for SIGNA Premier<\/span>","href":"t_TighteningConnectionsForSIGNAPremier_2.html","attributes":{"data-id":"id_2004634"},"menu":{"hasChildren":false},"tocID":"id_2004634-d46e98516","topics":[]},{"title":"Removing LOTO - MDP","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the MDP or the facility PDU before restoring power to these items. Facility-level LOTO must be done by an electrician.<\/p>","href":"t_Removing-LOTO-MDP-Premier_3.html","attributes":{"data-id":"id_2001935"},"menu":{"hasChildren":false},"tocID":"id_2001935-d46e98619","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_28.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e98728","topics":[]}]});